.shelf-fill-wrap {
    display: grid;
    gap: 0.3rem;
    min-width: 150px;
}

.shelf-fill-track {
    width: 100%;
    height: 10px;
    border-radius: 999px;
    background: #dfe7ef;
    overflow: hidden;
}

.shelf-fill-bar {
    height: 100%;
    border-radius: 999px;
}

.fill-low {
    background: #2e9f6f;
}

.fill-medium {
    background: #c88a16;
}

.fill-high {
    background: #c44536;
}

.store-metrics {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 0.8rem;
}

.metric-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.35rem 0.6rem;
    border-radius: 999px;
    border: 1px solid var(--border);
    background: #f4f8fc;
}

.metric-chip i {
    width: 18px;
    text-align: center;
}

.metric-cold {
    color: #216ab5;
    border-color: #b5d1ee;
}

.metric-mild {
    color: #2e7d4f;
    border-color: #bce4ca;
}

.metric-hot {
    color: #b84e1a;
    border-color: #f0c5ad;
}

.metric-dry {
    color: #9b691a;
    border-color: #efd9b8;
}

.metric-normal {
    color: #2e7d4f;
    border-color: #bce4ca;
}

.metric-humid {
    color: #1f6cae;
    border-color: #bbd8f2;
}

.store-map-canvas {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 260px;
    border-radius: 10px;
    border: 1px solid var(--border);
    margin-bottom: 0.9rem;
    overflow: hidden;
}

.leaflet-pane,
.leaflet-control,
.leaflet-top,
.leaflet-bottom {
    z-index: 400;
}

.store-map-global {
    height: 460px;
}

.three-toolbar {
    margin-bottom: 0.6rem;
}

.store-3d-canvas {
    width: 100%;
    height: 380px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: linear-gradient(180deg, #f6f7f9 0%, #e8edf2 100%);
    overflow: hidden;
}

.three-status {
    margin: 0.6rem 0 0;
    color: var(--text-muted);
    font-size: 0.88rem;
}

.three-legend {
    margin-top: 0.7rem;
    display: grid;
    gap: 0.55rem;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.three-legend-card {
    border: 1px solid var(--border);
    border-radius: 10px;
    background: #f8fbff;
    padding: 0.55rem 0.65rem;
}

.three-legend-card.active {
    border-color: var(--accent);
    box-shadow: 0 0 0 1px #0f8b8d33 inset;
}

.three-legend-head {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
    font-size: 0.85rem;
    margin-bottom: 0.3rem;
}

.three-legend-title {
    font-weight: 700;
}

.three-legend-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.2rem;
}

.three-legend-item {
    font-size: 0.83rem;
    color: var(--text-main);
}

.three-legend-empty {
    color: var(--text-muted);
    font-size: 0.82rem;
}

.map-store-card {
    width: 220px;
    display: grid;
    grid-template-columns: 70px 1fr;
    gap: 0.55rem;
    align-items: start;
}

.map-popup-image {
    width: 70px;
    height: 70px;
    border-radius: 10px;
    object-fit: cover;
    border: 1px solid var(--border);
}

.map-popup-image-empty {
    background: #edf3f8;
    display: grid;
    place-items: center;
    color: #476173;
}

.map-popup-info h4 {
    margin: 0;
    font-size: 0.92rem;
}

.map-popup-info p {
    margin: 0.2rem 0 0;
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.8rem;
    color: #2f4553;
}

.store-popup .leaflet-popup-content {
    margin: 0.55rem;
}

.store-map-marker-wrap {
    width: 54px;
    height: 54px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #fff;
    box-shadow: 0 5px 14px #00000033;
    background: #f5f8fb;
    display: grid;
    place-items: center;
}

.store-map-marker-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.store-map-marker-fallback {
    color: #486273;
    font-size: 1.2rem;
}

.tweets-panel ul {
    margin: 0.4rem 0 0;
    padding-left: 0;
    list-style: none;
}

.tweets-panel li {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    margin-bottom: 0.25rem;
}

.tweets-panel li i {
    margin-top: 0.1rem;
}

#inventory-item-submit:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.empty-state {
    color: var(--text-muted);
    text-align: center;
    padding: 0.8rem;
}

.global-alert {
    margin: 0.8rem 1rem 0;
    border-radius: 10px;
    padding: 0.7rem 0.9rem;
    font-weight: 600;
}

.hidden {
    display: none;
}

.alert-error {
    background: #ffe3de;
    color: #8a2619;
}

.alert-success {
    background: #dcf8ea;
    color: #186446;
}

.modal {
    border: 0;
    border-radius: 12px;
    width: min(560px, 95vw);
    padding: 0;
}

.modal::backdrop {
    background: #0d1a2388;
}

.modal form {
    padding: 1rem;
    display: grid;
    gap: 0.7rem;
}

.modal label,
.modal fieldset {
    display: grid;
    gap: 0.3rem;
    margin: 0;
    border: 0;
    padding: 0;
}

.modal fieldset label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.row-inline {
    display: grid;
    grid-template-columns: 70px 1fr;
    gap: 0.5rem;
}

.row-inline-double {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

#store-inventory-form .row-inline {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.field-error {
    min-height: 1.1em;
    color: var(--danger);
    font-size: 0.78rem;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
}

.uml-wrap {
    overflow: auto;
}

.footer {
    padding: 0.8rem;
    text-align: center;
    color: var(--text-muted);
}

body[data-theme="dark"] .group-row {
    background: #223540;
}

body[data-theme="dark"] .group-row td {
    border-bottom-color: #35505f;
}

body[data-theme="dark"] .shelf-fill-track {
    background: #2c3f4b;
}

body[data-theme="dark"] .three-legend-card {
    background: #1d2e39;
    border-color: #2f4554;
}

body[data-theme="dark"] .three-legend-card.active {
    background: #223946;
    box-shadow: 0 0 0 1px #64d2c144 inset;
}

@media (max-width: 1024px) {
    .layout-grid {
        grid-template-columns: 1fr;
    }

    .notifications-panel {
        position: static;
        max-height: none;
    }

    .store-map-global {
        height: 320px;
    }

    .store-3d-canvas {
        height: 300px;
    }
}

@media (max-width: 640px) {
    .header {
        flex-direction: column;
        align-items: flex-start;
    }

    .top-nav {
        overflow-x: auto;
    }

    .toolbar-actions {
        width: 100%;
    }

    .toolbar-actions input {
        width: 100%;
    }
}

